INSERT INTO public.products
  (id, name, category, brand, price, old_price, image, badge, description, featured, active)
VALUES
  (1, 'Istanbul Agop Traditional Clap Stack Set (11"/13"/15") CSFX', 'pratos', 'istanbul', 2999.00, '3499.00', '/produtos/pratos/clap-stack-set.jpg', 'Effect', 'O Istanbul Agop Traditional Clap Stack Set é uma coleção indispensável para bateristas que buscam um som autêntico e versátil. Disponível em três tamanhos — 11", 13" e 15" — este conjunto é ideal para diversos estilos musicais, desde o jazz sutil até o rock enérgico. Com design clássico e acabamento de alta qualidade, oferece um som vibrante, cheio de nuances e caráter. A construção artesanal e as técnicas de martelagem especializadas proporcionam uma resposta rápida e um ataque explosivo.', true, true),
  (2, 'Prato Istanbul Agop Xist Dry Dark Brilliant Crash 19"', 'pratos', 'istanbul', 2099.00, '2499.00', '/produtos/pratos/crash-19-xist-dry-dark-brilliant.jpg', 'Novo', 'As linhas "Dry Dark" possuem características sonoras mais particulares, inclinação para ritmos mais modernos, como Worship, Drum N\'' Bass e estilos que envolvem misturas com elementos eletrônicos. O Prato Istanbul Agop Xist Dry Dark Brilliant Crash 19" possui timbre grave, dark e trash, mas com um ataque brilhante e preciso. Prato com espessura fina, que ao atacado possui decay curto, mas cortante. Pelo seu martelamento profundo, pode ser até usado como ride quando tocado mais leve. É um dos queridinhos da marca. Cada prato é feito à mão, garantindo durabilidade e sonoridade exclusiva.', true, true),
  (3, 'Prato Istanbul Agop "Joey Waronker" Signature Ride 24"', 'pratos', 'istanbul', 5499.00, '6299.00', '/produtos/pratos/ride-24-joey-waronker.jpg', 'Signature', 'O Prato Istanbul Agop "Joey Waronker" Signature Ride 24" é projetado para bateristas que buscam um som distintivo e poderoso. Com design elegante e acabamento impecável, oferece um som rico e profundo, perfeito para diversos estilos musicais, desde o jazz sofisticado até o rock enérgico. Sua construção artesanal e técnicas de martelagem especializadas garantem uma resposta rápida e um ataque impressionante. Desenvolvida para atender às exigências de músicos de alto nível, a série Signature combina tradição e inovação.', true, true),
  (4, 'Prato Istanbul Agop Xist Ion Dark Trash 19"', 'pratos', 'istanbul', 2099.00, '2399.00', '/produtos/pratos/trash-19-xist-ion-dark.jpg', 'Effect', 'A série XIST é a que possui mais modelos dentre as linhas da Istanbul Agop. Isso significa que as possibilidades que você pode alcançar com esses pratos não têm fim. Todos os pratos da série são feitos sob técnicas modernas de produção combinadas com processos tradicionais de fabricação de pratos manuais que oferecem aos bateristas uma seleção diversificada de sons, do clássico ao inovador. O Prato Istanbul Agop XIST "ION" Dark Trash 19" tem como característica principal sua complexidade que é diferente de todos os outros pratos da série. Possui resposta rápida ao toque e decay curto, com timbre grave e "trash". Sua complexidade permite que o baterista também possa usá-lo como ride, desde que toque de forma mais suave.', true, true),
  (5, 'Chimbal Istanbul Agop Xist Dry Dark Brilliant Hi-Hat 15"', 'pratos', 'istanbul', 2799.00, NULL, '/produtos/pratos/hihat-15-xist-dry-dark-brilliant.jpg', 'Premium', 'As linhas "ION", "Dry Dark" e "Dry Dark Brilliant" possuem características sonoras mais particulares, com inclinação para ritmos mais modernos, como Worship, Drum N\'' Bass e estilos que envolvem misturas com elementos eletrônicos. Têm timbres com corte rápido e decay curto, além de tonalidade mais grave e "trash". O Chimbal Istanbul Agop Xist Dry Dark Brilliant Hi-Hat 15" possui timbre grave, dark e trash, mas com um ataque brilhante e preciso. Prato "top" muito fino, combinado com um prato "bottom" médio-pesado, que também soa muito bem usado como stack. Quando não emparelhados, o prato superior cria um crash explosivo, porém seco.', true, true),
  (6, 'Prato Istanbul Agop "Special Jazz Edition" Ride 24"', 'pratos', 'istanbul', 5699.00, NULL, '/produtos/pratos/ride-24-special-jazz.jpg', 'Premium', 'O Prato Istanbul Agop "Special Jazz Edition" Ride 24" é uma edição especial desenvolvida especificamente para bateristas de jazz que buscam um som autêntico e versátil. Liga Bronze B20, conhecida por sua durabilidade e qualidade sonora superior. Acabamento tradicional, com martelamento artesanal e lathing refinado, conferindo um visual clássico e sonoridade autêntica. Produção feita à mão na Turquia, garantindo a individualidade de cada peça. Com suas ranhuras características, este ride oferece um som quente, rico em harmônicos e com excelente definição de ponta de baqueta.', true, true),
  (8, 'Chimbal Istanbul Agop "Special Jazz Edition" Hi-Hat 14"', 'pratos', 'istanbul', 3999.00, NULL, '/produtos/pratos/hihat-14-special-jazz.jpg', 'Premium', 'O Chimbal Istanbul Agop "Special Jazz Edition" Hi-Hat 14" faz parte da linha especial desenvolvida para bateristas de jazz que buscam autenticidade sonora. Com liga Bronze B20 e acabamento tradicional com lathing refinado e ranhuras características, oferece um som clássico e versátil. Produzido à mão na Turquia, garante qualidade artesanal e sonoridade única. Perfeito para quem busca aquele "chick" definido e wash controlado do jazz tradicional.', true, true),
  (9, 'Chimbal Istanbul Agop Traditional Jazz Hi-Hats 15"', 'pratos', 'istanbul', 3999.00, NULL, '/produtos/pratos/hihat-15-traditional-jazz.jpg', 'Premium', 'Istanbul Agop Traditional Jazz Hi-Hats, das versões de 14″ e 15″, mostrando o acabamento tradicional, o trabalho manual com bronze B20 e o look artesanal característico. A série Traditional Jazz é parte da linha Traditional, que exibe excelência artesanal com afinação lathe em ambos os lados, resultando em timbres ricos, ressonantes e altamente musicais', false, true),
  (10, 'Chimbal Istanbul Agop Traditional Jazz Hi-Hats 14"', 'pratos', 'istanbul', 3599.00, NULL, '/produtos/pratos/hihat-14-traditional-jazz.jpg', 'Premium', 'Istanbul Agop Traditional Jazz Hi-Hats, das versões de 14″ e 15″, mostrando o acabamento tradicional, o trabalho manual com bronze B20 e o look artesanal característico. A série Traditional Jazz é parte da linha Traditional, que exibe excelência artesanal com afinação lathe em ambos os lados, resultando em timbres ricos, ressonantes e altamente musicais', false, true),
  (11, 'Prato Istanbul Agop "Mel Lewis" Signature Ride 22"', 'pratos', 'istanbul', 4499.00, NULL, '/produtos/pratos/ride-22-mel-lewis.jpg', 'Signature', 'Liga (Alloy): Bronze B20 (níquel-estanho), feito à mão e com acabamento polido (brilliant/glossy). Fabricado com base em protótipos usados por Mel Lewis, em prol de autenticidade sonora e estética clássica turca', false, true),
  (12, 'Prato Istanbul Agop Traditional Dark Ride 22"', 'pratos', 'istanbul', 3999.00, NULL, '/produtos/pratos/ride-22-traditional-dark.jpg', 'Novo', 'Istanbul Agop 22″ Traditional Dark Ride, um belo prato feito à mão com acabamento tradicional, ideal para seu visual e sonoridade únicos. Material: Bronze B20 (níquel e estanho). Acabamento: Latonado (lathed) por cima e por baixo, com aparência tradicional, artesanal e visual clássico. Feito à mão: Sim, cada exemplar é hand-hammered por artesãos turcos', false, true),
  (13, 'Prato Istanbul Agop Traditional Dark Ride 21"', 'pratos', 'istanbul', 3699.00, NULL, '/produtos/pratos/ride-21-traditional-dark.jpg', 'Novo', 'Istanbul Agop 21″ Traditional Dark Ride, um belo prato feito à mão com acabamento tradicional, ideal para seu visual e sonoridade únicos. Material: Bronze B20 (níquel e estanho). Acabamento: Latonado (lathed) por cima e por baixo, com aparência tradicional, artesanal e visual clássico. Feito à mão: Sim, cada exemplar é hand-hammered por artesãos turcos', false, true),
  (14, 'Prato Istanbul Agop Traditional Dark Crash 24"', 'pratos', 'istanbul', 4599.00, NULL, '/produtos/pratos/crash-24-traditional-dark.jpg', 'Novo', 'Istanbul Agop 24″ Traditional Dark Crash, um belo prato feito à mão com acabamento tradicional, ideal para seu visual e sonoridade únicos. Material: Bronze B20 (níquel e estanho). Acabamento: Latonado (lathed) por cima e por baixo, com aparência tradicional, artesanal e visual clássico. Feito à mão: Sim, cada exemplar é hand-hammered por artesãos turcos', false, true),
  (15, 'Prato Istanbul Agop Traditional Medium Ride 21"', 'pratos', 'istanbul', 3699.00, NULL, '/produtos/pratos/ride-21-traditional-medium.jpg', 'Novo', 'Istanbul Agop 21″ Traditional Medium Ride, um belo prato feito à mão com acabamento tradicional, ideal para seu visual e sonoridade únicos. Material: Bronze B20 (níquel e estanho). Acabamento: Latonado (lathed) por cima e por baixo, com aparência tradicional, artesanal e visual clássico. Feito à mão: Sim, cada exemplar é hand-hammered por artesãos turcos', false, true),
  (16, 'Prato Istanbul Agop Traditional Medium Crash 16"', 'pratos', 'istanbul', 2149.00, NULL, '/produtos/pratos/crash-16-traditional-medium.jpg', 'Novo', 'A SÉRIE TRADITIONAL - Os pratos da série Traditional são completamente torneados na parte superior e inferior, produzindo tons ricos e quentes e uma presença altamente musical. Eles estão disponíveis em gramaturas que variam de paperthin a heavy, oferecendo uma ampla variedade de opções para complementar qualquer estilo de música. É uma série que tem uma sonoridade versátil, funcionando muito bem para praticamente todos os estilos. CARACTERÍSTICAS DO PRATO - O Prato Istanbul Agop Traditional Medium Crash 16" possui sonoridade média, com espessura também média. É um prato com ataque cortante, que combina muito bem com pratos de diversas séries. Bem pronunciado, possui bom volume e tem timbre diferenciado, mesmo tendo aquela sobra dark que a série Traditional costuma ter como característica marcante. CONSTRUÇÃO DE ALTA QUALIDADE - Cada prato da Istanbul Agop é feito à mão, assegurando não apenas durabilidade, mas também uma sonoridade única que se adapta ao seu estilo musical. A marca Istanbul Agop exemplifica a excelência artesanal da marca, garantindo um instrumento robusto e de destaque em qualquer performance. Transforme suas performances e descubra novas texturas sonoras com o Prato Istanbul Agop Traditional Medium Crash 16"', false, true),
  (17, 'Prato Istanbul Agop Traditional Medium Crash 20"', 'pratos', 'istanbul', 3399.00, NULL, '/produtos/pratos/crash-20-traditional-medium.jpg', 'Novo', 'A SÉRIE TRADITIONAL - Os pratos da série Traditional são completamente torneados na parte superior e inferior, produzindo tons ricos e quentes e uma presença altamente musical. Eles estão disponíveis em gramaturas que variam de paperthin a heavy, oferecendo uma ampla variedade de opções para complementar qualquer estilo de música. É uma série que tem uma sonoridade versátil, funcionando muito bem para praticamente todos os estilos. CARACTERÍSTICAS DO PRATO - O Prato Istanbul Agop Traditional Medium Crash possui sonoridade média, com espessura também média. É um prato com ataque cortante, que combina muito bem com pratos de diversas séries. Bem pronunciado, possui bom volume e tem timbre diferenciado, mesmo tendo aquela sobra dark que a série Traditional costuma ter como característica marcante. CONSTRUÇÃO DE ALTA QUALIDADE - Cada prato da Istanbul Agop é feito à mão, assegurando não apenas durabilidade, mas também uma sonoridade única que se adapta ao seu estilo musical. A marca Istanbul Agop exemplifica a excelência artesanal da marca, garantindo um instrumento robusto e de destaque em qualquer performance. Transforme suas performances e descubra novas texturas sonoras com o Prato Istanbul Agop Traditional Medium Crash 20"', false, true),
